-- 1. Table: public.products
CREATE TABLE IF NOT EXISTS "products" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "slug" TEXT NOT NULL UNIQUE,
    "name" TEXT NOT NULL,
    "tagline" TEXT NOT NULL,
    "price" DOUBLE PRECISION NOT NULL,
    "originalPrice" DOUBLE PRECISION NOT NULL,
    "category" TEXT NOT NULL,
    "flowerType" TEXT NOT NULL,
    "stemCount" INTEGER NOT NULL,
    "rating" DOUBLE PRECISION NOT NULL,
    "reviewCount" INTEGER NOT NULL,
    "isBestseller" BOOLEAN NOT NULL DEFAULT false,
    "isNew" BOOLEAN NOT NULL DEFAULT false,
    "image" TEXT NOT NULL,
    "symbolism" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "occasionJson" TEXT NOT NULL DEFAULT '[]',
    "galleryJson" TEXT NOT NULL DEFAULT '[]',
    "careTipsJson" TEXT NOT NULL DEFAULT '[]',
    "sizesJson" TEXT NOT NULL DEFAULT '[]',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO "products" ("id", "slug", "name", "tagline", "price", "originalPrice", "category", "flowerType", "stemCount", "rating", "reviewCount", "isBestseller", "isNew", "image", "symbolism", "description", "occasionJson", "galleryJson", "careTipsJson", "sizesJson", "createdAt") VALUES ('fl-01', 'velvet-scarlet-grand-roses', 'Velvet Scarlet Grand Roses', 'Deep crimson Ecuadorian long-stem roses hand-tied with Italian ruscus', 1799, 2199, 'romance', 'Roses', 18, 4.9, 142, true, false, '/images/flowers/roses.svg', 'Symbolizes enduring devotion, heartfelt romance, and timeless elegance.', 'An iconic tribute to passion. These hand-selected, velvety crimson roses are cut fresh at sunrise from sustainable high-altitude farms. Arranged with fragrant silver dollar eucalyptus and framed in eco-chic tissue and French grosgrain ribbon.', '["Romance","Anniversary"]', '["/images/flowers/roses.svg","https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=1200&q=85"]', '["Trim stems 1 inch at a 45-degree angle under lukewarm running water.","Place in clean vase with cold water and included flower nutrient packet.","Replenish fresh water every 48 hours for up to 10 days of vibrant bloom."]', '[{"name":"Standard (12 Stems)","price":1799,"multiplier":1},{"name":"Deluxe (18 Stems)","price":2399,"multiplier":1.34},{"name":"Grand Luxe (24 Stems)","price":2999,"multiplier":1.68}]', '2026-10-15T11:00:41.095Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "products" ("id", "slug", "name", "tagline", "price", "originalPrice", "category", "flowerType", "stemCount", "rating", "reviewCount", "isBestseller", "isNew", "image", "symbolism", "description", "occasionJson", "galleryJson", "careTipsJson", "sizesJson", "createdAt") VALUES ('fl-02', 'provence-peach-peonies', 'Provence Peach Peony Whisper', 'Cloud-soft coral charm peonies paired with garden white ranunculus', 1999, 2499, 'luxury', 'Peonies', 15, 5, 88, true, true, '/images/flowers/peonies.svg', 'Represents prosperity, graceful good fortune, and joyful abundance.', 'A breathtaking cloud of delicate ruffles. As these premium Coral Charm peonies hydrate, they magically transform from rich sunset coral to soft champagne cream, making every single day a new visual delight.', '["Birthday","Anniversary","Congratulations"]', '["/images/flowers/peonies.svg","https://images.unsplash.com/photo-1526047932273-341f2a7631f9?auto=format&fit=crop&w=1200&q=85"]', '["Remove lower foliage so no leaves sit submerged in water.","Keep away from ripening fruit and drafty AC vents.","Give blooms room to unfurl naturally over 3-4 days."]', '[{"name":"Standard (10 Peonies + Fillers)","price":1999,"multiplier":1},{"name":"Deluxe (15 Peonies + Fillers)","price":2699,"multiplier":1.38},{"name":"Grand Luxe (20 Peonies + Luxe Vase)","price":3499,"multiplier":1.78}]', '2026-10-15T11:00:41.265Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "products" ("id", "slug", "name", "tagline", "price", "originalPrice", "category", "flowerType", "stemCount", "rating", "reviewCount", "isBestseller", "isNew", "image", "symbolism", "description", "occasionJson", "galleryJson", "careTipsJson", "sizesJson", "createdAt") VALUES ('fl-03', 'sunlit-tuscany-meadow', 'Sunlit Tuscany Meadow', 'Radiant golden sunflowers, chamomile daisies, and golden solidago', 1299, 1499, 'birthday', 'Sunflowers', 16, 4.8, 95, false, true, '/images/flowers/sunflowers.svg', 'Stands for optimism, warmth, vibrant longevity, and pure happiness.', 'Pure sunshine delivered right to their doorstep. A joyful countryside harvest arrangement designed to brighten any room, celebrate milestone birthdays, or send an energetic pick-me-up.', '["Birthday","Thank You","Just Because"]', '["/images/flowers/sunflowers.svg","https://images.unsplash.com/photo-1597848212624-a19eb35e2651?auto=format&fit=crop&w=1200&q=85"]', '["Sunflowers are thirsty blooms! Check water level twice daily.","Display in bright, indirect natural sunlight.","Mist lightly in the mornings for dewy freshness."]', '[{"name":"Standard Bouquet","price":1299,"multiplier":1},{"name":"Deluxe (Adds Garden Chamomile & Lilies)","price":1799,"multiplier":1.39},{"name":"Grand Luxe Feast","price":2299,"multiplier":1.8}]', '2026-10-15T11:00:41.346Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "products" ("id", "slug", "name", "tagline", "price", "originalPrice", "category", "flowerType", "stemCount", "rating", "reviewCount", "isBestseller", "isNew", "image", "symbolism", "description", "occasionJson", "galleryJson", "careTipsJson", "sizesJson", "createdAt") VALUES ('fl-04', 'celestial-white-lily-symphony', 'Celestial Lily & Orchid Symphony', 'Fragrant Casablanca oriental lilies, white cymbidium orchids & snapdragons', 1899, 2199, 'sympathy', 'Lilies', 14, 4.9, 112, true, false, '/images/flowers/lilies.svg', 'Stands for serenity, renewed hope, spiritual peace, and gentle comfort.', 'An ethereal composition of pure white Casablanca lilies radiating sublime fragrance, softened with cascade cymbidium orchids and frosty eucalyptus. Prepared with immense care to offer quiet solace and honor precious memories.', '["Sympathy","Anniversary","Thank You"]', '["/images/flowers/lilies.svg","https://images.unsplash.com/photo-1508615039623-a25605d2b022?auto=format&fit=crop&w=1200&q=85"]', '["Gently pluck pollen anthers when buds open to prevent surface staining.","Lilies will steadily unfurl over 7 to 12 days.","Keep away from curious household pets."]', '[{"name":"Standard Serenity","price":1899,"multiplier":1},{"name":"Deluxe Majesty","price":2499,"multiplier":1.33},{"name":"Grand Luxe Memorial Stand","price":3299,"multiplier":1.75}]', '2026-10-15T11:00:41.429Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "products" ("id", "slug", "name", "tagline", "price", "originalPrice", "category", "flowerType", "stemCount", "rating", "reviewCount", "isBestseller", "isNew", "image", "symbolism", "description", "occasionJson", "galleryJson", "careTipsJson", "sizesJson", "createdAt") VALUES ('fl-05', 'amsterdam-dawn-pastel-tulips', 'Amsterdam Dawn Pastel Tulips', 'A vibrant kaleidoscope of Dutch fringed, parrot, and double-petal tulips', 1399, 1599, 'birthday', 'Tulips', 25, 4.7, 64, false, true, '/images/flowers/tulips.svg', 'Reflects playful romance, new beginnings, and refreshing spring renewal.', 'Directly flown in from historic Dutch bulb estates. These multicolored French and fringed tulips continue to playfully grow towards the light in your vase, creating a living work of dynamic art.', '["Birthday","Congratulations","Just Because"]', '["/images/flowers/tulips.svg","https://images.unsplash.com/photo-1520763185298-1b434c919102?auto=format&fit=crop&w=1200&q=85"]', '["Tulips love ice-cold water! Add a couple of ice cubes daily.","Pin-prick stem just below the bloom to prevent droop.","Stems will grow 1-2 inches inside the vase."]', '[{"name":"Standard (20 Stems)","price":1399,"multiplier":1},{"name":"Deluxe (30 Stems)","price":1799,"multiplier":1.29},{"name":"Grand Luxe (45 Stems)","price":2399,"multiplier":1.73}]', '2026-10-15T11:00:41.517Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "products" ("id", "slug", "name", "tagline", "price", "originalPrice", "category", "flowerType", "stemCount", "rating", "reviewCount", "isBestseller", "isNew", "image", "symbolism", "description", "occasionJson", "galleryJson", "careTipsJson", "sizesJson", "createdAt") VALUES ('fl-06', 'boho-golden-dune-everlasting', 'Boho Golden Dune Everlasting', 'Naturally dried pampas plumes, sun-bleached palms & preserved lavender', 1599, 1899, 'dried', 'Dried Bouquets', 20, 4.9, 77, true, false, '/images/flowers/dried.svg', 'Celebrates timeless constancy, mindfulness, and enduring aesthetic grace.', 'No water or maintenance required. Sustainably harvested and preserved blooms that maintain their sculptural texture and earthy elegance for up to 3 years. A design-forward centerpiece for modern interiors.', '["Congratulations","Thank You","Just Because"]', '["/images/flowers/dried.svg","https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=1200&q=85"]', '["Never put in water! Dried florals thrive in dry areas.","Keep away from high humidity like steamy bathrooms.","Lightly blow-dry on cool/low speed once a month to remove dust."]', '[{"name":"Standard Arrangement","price":1599,"multiplier":1},{"name":"Deluxe Ceramic Pot Ensemble","price":2199,"multiplier":1.38}]', '2026-10-15T11:00:41.601Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "products" ("id", "slug", "name", "tagline", "price", "originalPrice", "category", "flowerType", "stemCount", "rating", "reviewCount", "isBestseller", "isNew", "image", "symbolism", "description", "occasionJson", "galleryJson", "careTipsJson", "sizesJson", "createdAt") VALUES ('fl-07', 'royal-magenta-phalaenopsis-orchid', 'Royal Magenta Phalaenopsis Orchid', 'Living double-spike cascade orchid in a handcrafted textured stone vessel', 2199, 2699, 'luxury', 'Orchids', 2, 5, 53, false, true, '/images/flowers/orchids.svg', 'Signifies refined luxury, exquisite beauty, and stately strength.', 'An architectural living treasure. Two majestic cascading spikes boasting up to 16 velvet-textured jewel-toned blossoms that bloom continuously for over two months.', '["Anniversary","Congratulations","Thank You"]', '["/images/flowers/orchids.svg","https://images.unsplash.com/photo-1525310072745-f49212b5ac6d?auto=format&fit=crop&w=1200&q=85"]', '["Water with 3 ice cubes once every 7-10 days.","Provide filtered, bright morning window light.","Do not allow roots to stand in stagnant drainage water."]', '[{"name":"Double Stem in Clay Pot","price":2199,"multiplier":1},{"name":"Triple Stem in Artisanal Vessel","price":3099,"multiplier":1.41}]', '2026-10-15T11:00:41.682Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "products" ("id", "slug", "name", "tagline", "price", "originalPrice", "category", "flowerType", "stemCount", "rating", "reviewCount", "isBestseller", "isNew", "image", "symbolism", "description", "occasionJson", "galleryJson", "careTipsJson", "sizesJson", "createdAt") VALUES ('fl-08', 'enchanted-english-garden', 'Enchanted English Garden Romance', 'David Austin garden roses, lilac delphinium, blush sweet peas & herbs', 2099, 2499, 'romance', 'Garden Roses', 22, 4.9, 134, true, false, '/images/flowers/garden.svg', 'Whispers poetic affection, nostalgia, and enchanting wonder.', 'Like a freshly plucked stroll through the Cotswolds. Layered with heirloom scented garden roses, cascading cornflower blues, and aromatic spearmint foliage.', '["Romance","Birthday","Anniversary"]', '["/images/flowers/garden.svg","https://images.unsplash.com/photo-1561181286-d3fee7d55364?auto=format&fit=crop&w=1200&q=85"]', '["Trim stems recutting every 2 days.","Keep away from direct heat lamps.","Mist gently on warm afternoons."]', '[{"name":"Standard (16 Stems)","price":2099,"multiplier":1},{"name":"Deluxe (24 Stems)","price":2799,"multiplier":1.32},{"name":"Grand Luxe (32 Stems + Vintage Vase)","price":3799,"multiplier":1.8}]', '2026-10-15T11:00:41.766Z') ON CONFLICT ("id") DO NOTHING;

